package dev.onix.client.cosmetics;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import dev.onix.client.OnixClient;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Every cosmetic, read from assets/onix/cosmetics/catalog.json (generated by tools/cosmetics.py).
 * The launcher reads the same file for its previews.
 */
public final class CosmeticCatalog {
    public enum Tier { COMMON, RARE, EPIC, LEGENDARY }

    /** One cube: corners in model pixels, a palette index (0-9, see tools/cosmetics.py) or a fixed ARGB colour, and full-bright glow. */
    public record Cube(float x1, float y1, float z1, float x2, float y2, float z2, int paletteIndex, int fixedColor, boolean glow) {
        public int color(int[] palette) {
            if (paletteIndex < 0) return fixedColor;
            return palette[Math.min(paletteIndex, palette.length - 1)];
        }
    }

    /** Model animation (bob, spin, flap, orbit …) or part animation (rot, pulse, blink, twinkle …). */
    public record Anim(String type, float amp, float speed, float base, float range, float[] pivot,
                       int count, float radius, float y, float height, float wobble,
                       String axis, float phase, float period, float dur) {
        static final Anim STATIC = new Anim("static", 0, 0, 0, 0, new float[3], 0, 0, 0, 0, 0, "y", 0, 0, 0);
    }

    /** A group of cubes with its own animation inside the model (a wagging tail, a blinking eye). */
    public record Part(Anim anim, List<Cube> cubes, List<Part> parts) {}

    public record Model(String id, String slot, String name, String anchor, Anim anim, List<Cube> cubes, List<Part> parts, String extra) {
        public boolean onHead() {
            return "head".equals(anchor);
        }
    }

    /** price in coins; 0 = free for everyone */
    public record Item(String id, String name, Cosmetics.Slot slot, String pattern, String palette, String model, String texture, Tier tier, int price) {
        public boolean isCape() {
            return slot == Cosmetics.Slot.CAPE;
        }
    }

    private static final Map<String, int[]> PALETTES = new LinkedHashMap<>();
    private static final Map<String, String> PALETTE_NAMES = new LinkedHashMap<>();
    private static final Map<String, JsonArray> PATTERNS = new HashMap<>();
    /** pattern id → {frames, ticks per frame} for animated capes */
    private static final Map<String, int[]> PATTERN_ANIM = new HashMap<>();
    private static final Map<String, String[]> EMBLEMS = new HashMap<>();
    private static final Map<String, Model> MODELS = new HashMap<>();
    private static final Map<String, Item> ITEMS = new LinkedHashMap<>();
    private static final Map<String, String> ALIASES = new HashMap<>();
    private static final Map<Cosmetics.Slot, List<Item>> BY_SLOT = new HashMap<>();
    private static boolean loaded;

    private CosmeticCatalog() {}

    public static synchronized void load() {
        if (loaded) return;
        loaded = true;
        try (InputStream in = CosmeticCatalog.class.getResourceAsStream("/assets/onix/cosmetics/catalog.json")) {
            if (in == null) throw new IllegalStateException("catalog.json is missing from the mod");
            parse(JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject());
            OnixClient.LOGGER.info("Loaded {} cosmetics", ITEMS.size());
        } catch (Exception e) {
            OnixClient.LOGGER.error("Could not load the cosmetics catalog", e);
        }
    }

    /** Package-private so tests can feed a catalog without the game. */
    static void parse(JsonObject root) {
        for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("palettes").entrySet()) {
            JsonObject p = e.getValue().getAsJsonObject();
            JsonArray colors = p.getAsJsonArray("colors");
            int[] argb = new int[colors.size()];
            for (int i = 0; i < argb.length; i++) argb[i] = hex(colors.get(i).getAsString());
            PALETTES.put(e.getKey(), argb);
            PALETTE_NAMES.put(e.getKey(), p.get("name").getAsString());
        }
        for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("emblems").entrySet()) {
            JsonArray rows = e.getValue().getAsJsonArray();
            String[] mask = new String[rows.size()];
            for (int i = 0; i < mask.length; i++) mask[i] = rows.get(i).getAsString();
            EMBLEMS.put(e.getKey(), mask);
        }
        for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("patterns").entrySet()) {
            JsonObject p = e.getValue().getAsJsonObject();
            PATTERNS.put(e.getKey(), p.getAsJsonArray("ops"));
            if (p.has("anim")) {
                JsonObject a = p.getAsJsonObject("anim");
                PATTERN_ANIM.put(e.getKey(), new int[]{Math.max(1, a.get("frames").getAsInt()), Math.max(1, a.get("ticks").getAsInt())});
            }
        }
        for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("models").entrySet()) {
            JsonObject m = e.getValue().getAsJsonObject();
            MODELS.put(e.getKey(), new Model(e.getKey(), m.get("slot").getAsString(), m.get("name").getAsString(),
                    m.get("anchor").getAsString(), anim(m.getAsJsonObject("anim")), cubes(m.getAsJsonArray("cubes")), parts(m),
                    m.has("extra") ? m.get("extra").getAsString() : null));
        }
        for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("aliases").entrySet()) ALIASES.put(e.getKey(), e.getValue().getAsString());
        for (JsonElement el : root.getAsJsonArray("items")) {
            JsonObject o = el.getAsJsonObject();
            Cosmetics.Slot slot = Cosmetics.Slot.byKey(o.get("slot").getAsString());
            if (slot == null) continue;
            Item item = new Item(o.get("id").getAsString(), o.get("name").getAsString(), slot, str(o, "pattern"), str(o, "palette"),
                    str(o, "model"), str(o, "texture"), Tier.valueOf(o.get("tier").getAsString().toUpperCase(Locale.ROOT)),
                    o.has("price") ? o.get("price").getAsInt() : 0);
            ITEMS.put(item.id(), item);
            BY_SLOT.computeIfAbsent(slot, k -> new ArrayList<>()).add(item);
        }
    }

    private static List<Cube> cubes(JsonArray array) {
        List<Cube> cubes = new ArrayList<>();
        if (array == null) return cubes;
        for (JsonElement c : array) {
            JsonArray a = c.getAsJsonArray();
            JsonElement col = a.get(6);
            boolean fixed = col.getAsJsonPrimitive().isString();
            cubes.add(new Cube(a.get(0).getAsFloat(), a.get(1).getAsFloat(), a.get(2).getAsFloat(),
                    a.get(3).getAsFloat(), a.get(4).getAsFloat(), a.get(5).getAsFloat(),
                    fixed ? -1 : col.getAsInt(), fixed ? hex(col.getAsString()) : 0, a.get(7).getAsInt() == 1));
        }
        return List.copyOf(cubes);
    }

    private static List<Part> parts(JsonObject node) {
        if (!node.has("parts")) return List.of();
        List<Part> parts = new ArrayList<>();
        for (JsonElement el : node.getAsJsonArray("parts")) {
            JsonObject p = el.getAsJsonObject();
            parts.add(new Part(anim(p.getAsJsonObject("anim")), cubes(p.getAsJsonArray("cubes")), parts(p)));
        }
        return List.copyOf(parts);
    }

    private static Anim anim(JsonObject a) {
        if (a == null) return Anim.STATIC;
        float[] pivot = new float[3];
        if (a.has("pivot")) {
            JsonArray p = a.getAsJsonArray("pivot");
            for (int i = 0; i < 3; i++) pivot[i] = p.get(i).getAsFloat();
        }
        return new Anim(a.get("type").getAsString(), f(a, "amp"), f(a, "speed"), f(a, "base"), f(a, "range"), pivot,
                (int) f(a, "count"), f(a, "radius"), f(a, "y"), f(a, "height"), f(a, "wobble"),
                a.has("axis") ? a.get("axis").getAsString() : "y", f(a, "phase"), f(a, "period"), f(a, "dur"));
    }

    private static float f(JsonObject o, String key) {
        return o.has(key) ? o.get(key).getAsFloat() : 0f;
    }

    private static String str(JsonObject o, String key) {
        return o.has(key) ? o.get(key).getAsString() : null;
    }

    private static int hex(String s) {
        return 0xFF000000 | Integer.parseInt(s.substring(1), 16);
    }

    // ---------------------------------------------------------------- lookups

    public static Item item(String id) {
        if (id == null) return null;
        load();
        Item item = ITEMS.get(id);
        return item != null ? item : ITEMS.get(ALIASES.get(id));
    }

    public static List<Item> items(Cosmetics.Slot slot) {
        load();
        return Collections.unmodifiableList(BY_SLOT.getOrDefault(slot, List.of()));
    }

    public static int count() {
        load();
        return ITEMS.size();
    }

    public static Model model(String id) {
        load();
        return id == null ? null : MODELS.get(id);
    }

    /** Used for items without a palette (the first, hand-drawn capes). */
    private static final int[] DEFAULT_PALETTE = {0xFF2A2A33, 0xFF18181E, 0xFF8B84FF, 0xFF0B0B0F, 0xFF5B57A0, 0xFF1A1A21, 0xFF524E8F, 0xFF121217, 0xFFC5C2FF, 0xFF060608};

    public static int[] palette(String id) {
        load();
        int[] p = PALETTES.get(id);
        return p != null ? p : DEFAULT_PALETTE;
    }

    public static String paletteName(String id) {
        return PALETTE_NAMES.getOrDefault(id, "");
    }

    public static List<String> paletteIds() {
        load();
        return List.copyOf(PALETTES.keySet());
    }

    /** Palette indices of a cape pattern's face (20 x 32) for one animation frame. */
    public static int[] capeIndices(String pattern, int frame) {
        load();
        JsonArray ops = PATTERNS.get(pattern);
        return ops == null ? new int[CapePattern.W * CapePattern.H] : CapePattern.indices(ops, EMBLEMS, frame);
    }

    /** {frames, ticks per frame}; {1, 1} for a still cape. */
    public static int[] capeAnim(String pattern) {
        load();
        return PATTERN_ANIM.getOrDefault(pattern, new int[]{1, 1});
    }
}
